                              const rows = (materialRates || []).map(m => {
                                const reqQty = (Number(m.qty || 0) * (1 + (Number(m.wastePct || 5) / 100))).toFixed(2);
                                const rateVal = currency === "USD" ? Number(m.basePriceUsd || 0) : Math.round(Number(m.basePriceUsd || 0) * exchangeRate);
                                const totalVal = (reqQty * rateVal).toFixed(2);
                                return [
                                  '"' + (m.code || 'MAT-BLD') + '"',
                                  '"' + (m.trade || 'General Building') + '"',
                                  '"' + (m.name || '').replace(/"/g, '""') + '"',
                                  '"' + (m.spec || 'Standard') + '"',
                                  m.qty || 0,
                                  (m.wastePct || 5) + "%",
                                  reqQty,
                                  '"' + (m.unit || 'nr') + '"',
                                  rateVal,
                                  totalVal,
                                  '"' + (m.source || 'Local Depot') + '"'
                                ].join(",");
                              });
